/// <summary>
/// Resolves a command/query workspace through the repository-wide identity policy and
/// propagates caller cancellation into bounded physical resolution.
/// </summary>
public static async Task<ResolvedUseCaseWorkspace> ResolveWorkspaceAsync(
    McpDbContext db,
    WorkspaceContext workspaceContext,
    string? workspacePath,
    CancellationToken cancellationToken)
{
    var resolved = !string.IsNullOrWhiteSpace(workspacePath)
        ? workspacePath.Trim()
        : workspaceContext.WorkspacePath;

    if (string.IsNullOrWhiteSpace(resolved))
        throw new InvalidOperationException("Workspace path is required for use case operations.");

    var resolution = await WorkspaceIdentity.ResolveAsync(
            resolved,
            s_workspaceIdentityResolutionTimeout,
            cancellationToken)
        .ConfigureAwait(false);

    var workspaceId = resolution.NormalizedPath;
    if (!string.Equals(db.CurrentWorkspaceId, workspaceId, StringComparison.OrdinalIgnoreCase))
        db.OverrideWorkspaceId(workspaceId);

    return new ResolvedUseCaseWorkspace(
        workspaceId,
        resolution.NormalizedPath,
        resolution.StorageKey);
}

/// <summary>Applies optional command/query workspace path override onto the scoped DbContext.</summary>
public static string ResolveWorkspaceId(McpDbContext db, WorkspaceContext workspaceContext, string? workspacePath)
{
    var resolved = !string.IsNullOrWhiteSpace(workspacePath)
        ? workspacePath.Trim()
        : workspaceContext.WorkspacePath;

    if (string.IsNullOrWhiteSpace(resolved))
        throw new InvalidOperationException("Workspace path is required for use case operations.");

    if (!string.Equals(db.CurrentWorkspaceId, resolved, StringComparison.OrdinalIgnoreCase))
        db.OverrideWorkspaceId(resolved);

    return resolved;
}

/// <summary>Clears soft-delete shadow properties so a durable row becomes visible again.</summary>
public static void ClearSoftDelete(McpDbContext db, object entity)
{
    var entry = db.Entry(entity);
    if (entry.Metadata.FindProperty("IsDeleted") is null)
        return;

    entry.State = EntityState.Modified;
    entry.Property("IsDeleted").CurrentValue = false;
    entry.Property("DeletedAtUtc").CurrentValue = null;
    entry.Property("DeletedBy").CurrentValue = null;
    entry.Property("DeleteReason").CurrentValue = null;
}

/// <summary>Loads a non-deleted use case aggregate with children, or null when not found.</summary>
public static async Task<UseCaseEntity?> LoadAggregateAsync(
    McpDbContext db,
    long useCaseId,
    CancellationToken cancellationToken)
{
    return await db.UseCases
        .Include(u => u.UseCaseActors)
        .ThenInclude(a => a.Actor)
        .Include(u => u.Flows)
        .ThenInclude(f => f.Steps)
        .ThenInclude(s => s.Actor)
        .Include(u => u.SpecialRequirements)
        .Include(u => u.ExtensionPoints)
        .Include(u => u.FrLinks)
        .FirstOrDefaultAsync(u => u.UseCaseId == useCaseId, cancellationToken)
        .ConfigureAwait(false);
}

/// <summary>
/// Ensures a functional requirement (kind fr) exists for the workspace; returns null error message when valid.
/// </summary>
public static async Task<string?> ValidateFrExistsAsync(
    McpDbContext db,
    string workspaceId,
    string frId,
    CancellationToken cancellationToken)
{
    if (string.IsNullOrWhiteSpace(frId))
        return "FrId is required.";

    var exists = await db.Requirements
        .AsNoTracking()
        .AnyAsync(
            r => r.WorkspaceId == workspaceId
                 && r.Kind == UseCaseConstants.FrKind
                 && r.Id == frId.Trim(),
            cancellationToken)
        .ConfigureAwait(false);

    return exists
        ? null
        : $"Functional requirement '{frId.Trim()}' was not found (Kind must be fr).";
}

/// <summary>Resolves the caller workspace id from the command path.</summary>
public static string ResolveCaller(string? workspacePath)
{
    var resolved = (workspacePath ?? string.Empty).Trim();
    if (resolved.Length == 0)
        throw new InvalidOperationException("Workspace path is required for product operations.");

    // FR-MCP-PATHNORM-001: compare with stored (canonical) workspace keys in the same form.
    return WorkspaceIdentity.CanonicalizeWorkspaceId(resolved);
}

/// <summary>Requires a registered, enabled, non-deleted workspace.</summary>
public static async Task<string?> RequireRegisteredEnabledWorkspaceAsync(
    McpDbContext db,
    string workspaceId,
    CancellationToken cancellationToken)
{
    var workspace = await db.Workspaces
        .IgnoreQueryFilters()
        .FirstOrDefaultAsync(w => w.WorkspaceId == workspaceId, cancellationToken)
        .ConfigureAwait(false);

    if (workspace is null || workspace.IsDeleted || !workspace.IsEnabled)
        return ProductResultCodes.BadRequestMsg("Workspace must be a registered enabled workspace.");

    return null;
}

/// <summary>Loads a non-deleted product by key, including memberships.</summary>
public static Task<ProductEntity?> LoadProductByKeyAsync(
    McpDbContext db,
    string key,
    CancellationToken cancellationToken)
{
    return db.Products
        .Include(p => p.Memberships)
        .FirstOrDefaultAsync(p => p.Key == key, cancellationToken);
}

/// <summary>True when a tracked entity has the soft-delete shadow flag set.</summary>
public static bool IsSoftDeleted(McpDbContext db, object entity)
{
    var entry = db.Entry(entity);
    if (entry.Metadata.FindProperty("IsDeleted") is null)
        return false;

    return entry.Property("IsDeleted").CurrentValue is true;
}

/// <summary>True when the caller is an active (non-deleted) member or owner.</summary>
public static bool IsActiveMember(McpDbContext db, ProductEntity product, string workspaceId)
{
    return product.Memberships.Any(m =>
        string.Equals(m.WorkspaceId, workspaceId, StringComparison.OrdinalIgnoreCase)
        && !IsSoftDeleted(db, m));
}

/// <summary>True when the caller owns the product.</summary>
public static bool IsOwner(ProductEntity product, string workspaceId)
    => string.Equals(product.OwnerWorkspaceId, workspaceId, StringComparison.OrdinalIgnoreCase);

/// <summary>
/// Visibility/auth for a read: missing or non-member is 404 (do not leak existence).
/// </summary>
public static string? RequireVisible(McpDbContext db, ProductEntity? product, string caller)
{
    if (product is null || IsSoftDeleted(db, product) || !IsActiveMember(db, product, caller))
        return ProductResultCodes.NotFoundMsg("Product was not found.");

    return null;
}

/// <summary>
/// Visibility/auth for an owner mutation. Outsiders get 404; members who are not owners get 403.
/// </summary>
public static string? RequireOwner(McpDbContext db, ProductEntity? product, string caller)
{
    if (product is null || IsSoftDeleted(db, product))
        return ProductResultCodes.NotFoundMsg("Product was not found.");

    if (IsOwner(product, caller))
        return null;

    if (IsActiveMember(db, product, caller))
        return ProductResultCodes.ForbiddenMsg("Only the owner may change this product.");

    return ProductResultCodes.NotFoundMsg("Product was not found.");
}

/// <summary>
/// Registers use case CQRS handlers, diagram service, and related infrastructure.
/// Call from both HTTP host (<c>Program.cs</c>) and STDIO host (<c>McpStdioHost.cs</c>).
/// </summary>
/// <param name="services">Service collection.</param>
/// <returns>The same service collection for chaining.</returns>
public static IServiceCollection AddUseCaseCqrs(this IServiceCollection services)
{
    ArgumentNullException.ThrowIfNull(services);

    services.AddSingleton<IUseCaseDiagramService, MermaidUseCaseDiagramService>();
    services.AddSingleton<IUseCaseUmlSerializationService, UseCaseUmlSerializationService>();

    services.AddTransient<ICommandHandler<CreateUseCaseCommand, UseCaseDetailDto>, CreateUseCaseCommandHandler>();
    services.AddTransient<ICommandHandler<UpdateUseCaseCommand, UseCaseDetailDto>, UpdateUseCaseCommandHandler>();
    services.AddTransient<ICommandHandler<DeleteUseCaseCommand, bool>, DeleteUseCaseCommandHandler>();
    services.AddTransient<ICommandHandler<AddUseCaseFlowCommand, UseCaseFlowDto>, AddUseCaseFlowCommandHandler>();
    services.AddTransient<ICommandHandler<AddUseCaseStepCommand, UseCaseStepDto>, AddUseCaseStepCommandHandler>();
    services.AddTransient<ICommandHandler<AttachUseCaseActorCommand, UseCaseActorDto>, AttachUseCaseActorCommandHandler>();
    services.AddTransient<ICommandHandler<LinkUseCaseToFrCommand, UseCaseFrLinkDto>, LinkUseCaseToFrCommandHandler>();
    services.AddTransient<ICommandHandler<UnlinkUseCaseFromFrCommand, bool>, UnlinkUseCaseFromFrCommandHandler>();
    services.AddTransient<ICommandHandler<CreateUseCaseFromFrCommand, UseCaseDetailDto>, CreateUseCaseFromFrCommandHandler>();
    services.AddTransient<ICommandHandler<SetUseCaseApprovalStatusCommand, UseCaseDetailDto>, SetUseCaseApprovalStatusCommandHandler>();
    services.AddTransient<ICommandHandler<SetUseCaseProductKeyCommand, UseCaseDetailDto>, SetUseCaseProductKeyCommandHandler>();
    services.AddTransient<ICommandHandler<PutUseCaseDiagramGraphCommand, UseCaseDiagramGraphDto>, PutUseCaseDiagramGraphCommandHandler>();

    services.AddTransient<IQueryHandler<GetUseCaseQuery, UseCaseDetailDto>, GetUseCaseQueryHandler>();
    services.AddTransient<IQueryHandler<ListUseCasesQuery, IReadOnlyList<UseCaseSummaryDto>>, ListUseCasesQueryHandler>();
    services.AddTransient<IQueryHandler<ListUseCasesByProductQuery, IReadOnlyList<UseCaseSummaryDto>>, ListUseCasesByProductQueryHandler>();
    services.AddTransient<IQueryHandler<GetUseCaseDiagramQuery, UseCaseDiagramDto>, GetUseCaseDiagramQueryHandler>();
    services.AddTransient<IQueryHandler<GetUseCaseDiagramGraphQuery, UseCaseDiagramGraphDto>, GetUseCaseDiagramGraphQueryHandler>();
    services.AddTransient<IQueryHandler<GetUseCasesForFrQuery, IReadOnlyList<LinkedUseCaseDto>>, GetUseCasesForFrQueryHandler>();
    services.AddTransient<IQueryHandler<GetUseCaseFrCoverageQuery, UseCaseFrCoverageDto>, GetUseCaseFrCoverageQueryHandler>();

    return services;

/// <summary>FR-MCP-USECASE-001: Creates a use case.</summary>
[HttpPost]
[ProducesResponseType(typeof(UseCaseDetailDto), StatusCodes.Status201Created)]
[ProducesResponseType(StatusCodes.Status400BadRequest)]
[ProducesResponseType(StatusCodes.Status404NotFound)]
[ProducesResponseType(StatusCodes.Status409Conflict)]
[RequiresUnreferencedCode("CQRS dispatcher uses reflection over handler types.")]
public async Task<ActionResult<UseCaseDetailDto>> CreateAsync(
    [FromBody] CreateUseCaseRequest? request,
    CancellationToken cancellationToken)
{
    if (request is null)
        return BadRequest(ClassifiedPayload(McpErrorClassifier.ValidationError, "Request body is required.", 400));

    var result = await _dispatcher.SendAsync(
        new CreateUseCaseCommand(GetWorkspacePath(), request),
        cancellationToken).ConfigureAwait(false);
    if (result.IsFailure)
        return MapFailure(result);

    return Created(
        new Uri($"/qbrainai/usecases/{result.Value!.UseCaseId}", UriKind.Relative),
        result.Value);

/// <summary>FR-MCP-USECASE-008: Sets approval status for a use case.</summary>
[HttpPost("{id:long}/approval")]
[ProducesResponseType(typeof(UseCaseDetailDto), StatusCodes.Status200OK)]
[RequiresUnreferencedCode("CQRS dispatcher uses reflection over handler types.")]
public async Task<ActionResult<UseCaseDetailDto>> SetApprovalAsync(
    long id,
    [FromBody] SetApprovalRequest? request,
    CancellationToken cancellationToken)
{
    if (request is null || string.IsNullOrWhiteSpace(request.Status))
        return BadRequest(ClassifiedPayload(McpErrorClassifier.ValidationError, "Status is required.", 400));

    var result = await _dispatcher.SendAsync(
        new SetUseCaseApprovalStatusCommand(GetWorkspacePath(), id, request.Status),
        cancellationToken).ConfigureAwait(false);
    if (result.IsFailure)
        return MapFailure(result);
    return Ok(result.Value);
}

/// <summary>FR-MCP-USECASE-009: Sets product membership key.</summary>
[HttpPost("{id:long}/product")]
[ProducesResponseType(typeof(UseCaseDetailDto), StatusCodes.Status200OK)]
[RequiresUnreferencedCode("CQRS dispatcher uses reflection over handler types.")]
public async Task<ActionResult<UseCaseDetailDto>> SetProductAsync(
    long id,
    [FromBody] SetProductRequest? request,
    CancellationToken cancellationToken)
{
    var result = await _dispatcher.SendAsync(
        new SetUseCaseProductKeyCommand(GetWorkspacePath(), id, request?.ProductKey),
        cancellationToken).ConfigureAwait(false);
    if (result.IsFailure)
        return MapFailure(result);
    return Ok(result.Value);
}

/// <summary>FR-MCP-PRODUCT-001: Create a product owned by the caller.</summary>
[HttpPost]
[ProducesResponseType(typeof(ProductDto), StatusCodes.Status201Created)]
[RequiresUnreferencedCode("CQRS dispatcher uses reflection over handler types.")]
public async Task<ActionResult<ProductDto>> CreateAsync(
    [FromBody] CreateProductRequest? request,
    CancellationToken cancellationToken)
{
    if (request is null)
        return BadRequest(new { error = "Request body is required." });

    var result = await _dispatcher.SendAsync(
        new CreateProductCommand(GetWorkspacePath(), request),
        cancellationToken).ConfigureAwait(false);
    if (result.IsFailure)
        return MapFailure(result.Error);

    return Created(
        new Uri($"/qbrainai/products/{result.Value!.Key}", UriKind.Relative),
        result.Value);
}
